<?php require 'header.php';$products=db()->query('SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();?><div class="admin-title row"><div><p>CATALOGUE</p><h2>Manage products</h2></div><a class="save" href="add-product.php">+ Add product</a></div><section class="admin-panel"><table><thead><tr><th>Product</th><th>Brand</th><th>Price</th><th>Stock</th><th>Condition</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td class="product-cell"><img src="<?=image_url($p['image'])?>" alt=""><span><?=e($p['name'])?></span></td><td><?=e($p['brand'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=e($p['condition'])?></td><td><a href="../product-details.php?id=<?=$p['id']?>" target="_blank">View</a> · <a href="edit-product.php?id=<?=$p['id']?>">Edit</a> · <a class="danger" href="delete-product.php?id=<?=$p['id']?>">Delete</a></td></tr><?php endforeach ?></tbody></table><?php if(!$products):?><p>No products yet.</p><?php endif ?></section><?php require 'footer.php'; ?>
